export interface WalkControlsProps {
  onEndWalk: (options?: { fromHold?: boolean }) => void;
  onCameraClick?: () => void;
  onPhotoSelected?: (file: File) => void;
  onMicClick?: () => void;
  disabled?: boolean;
}

export interface WalkControlsHandle {
  triggerCapture: () => void;
}

const HOLD_DURATION_MS = 1000;

export const WalkControls = React.forwardRef<WalkControlsHandle, WalkControlsProps>(
  function WalkControls(
    { onEndWalk, onCameraClick, onPhotoSelected, onMicClick, disabled = false },
    ref
  ) {
    const fileInputRef = useRef<HTMLInputElement | null>(null);
    const [isLiveCameraOpen, setIsLiveCameraOpen] = useState<boolean>(false);

    // Phones hand `<input capture>` to the native camera app. Everywhere else
    // (laptops, desktops) `capture` is ignored and only opens a file picker, which
    // reads as a broken camera button, so those get a live viewfinder instead.
    const openCamera = useCallback(() => {
      const canStream = typeof navigator !== 'undefined' && !!navigator.mediaDevices?.getUserMedia;
      const isTouchPrimary = typeof window !== 'undefined' && window.matchMedia('(pointer: coarse)').matches;
      if (canStream && !isTouchPrimary) {
        setIsLiveCameraOpen(true);
      } else {
        fileInputRef.current?.click();
      }
    }, []);

    React.useImperativeHandle(ref, () => ({
      triggerCapture: openCamera,
    }));

    const handleCameraClick = () => {
      if (onPhotoSelected) {
        openCamera();
      } else if (onCameraClick) {
        onCameraClick();
      }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
        onPhotoSelected?.(file);
        e.target.value = '';
      }
    };

    const [holdProgress, setHoldProgress] = useState<number>(0);
    const [isHolding, setIsHolding] = useState<boolean>(false);

    const startTimeRef = useRef<number | null>(null);
    const animationFrameRef = useRef<number | null>(null);
    const hasTriggeredRef = useRef<boolean>(false);

    const cancelHold = useCallback(() => {
      setIsHolding(false);
      startTimeRef.current = null;
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
        animationFrameRef.current = null;
      }
      setHoldProgress(0);
    }, []);

    const startHold = useCallback(() => {
      if (disabled) return;

      setIsHolding(true);
      hasTriggeredRef.current = false;
      startTimeRef.current = performance.now();

      const tick = (now: number) => {
        if (!startTimeRef.current) return;
        const elapsed = now - startTimeRef.current;
        const progress = Math.min(100, (elapsed / HOLD_DURATION_MS) * 100);
        setHoldProgress(progress);

        if (progress >= 100 && !hasTriggeredRef.current) {
          hasTriggeredRef.current = true;
          cancelHold();
          // Haptic feedback if supported
          if (typeof navigator !== 'undefined' && 'vibrate' in navigator) {
            try {
              navigator.vibrate?.(50);
            } catch {
              // Ignore haptic errors
            }
          }
          onEndWalk({ fromHold: true });
          return;
        }

        animationFrameRef.current = requestAnimationFrame(tick);
      };

      animationFrameRef.current = requestAnimationFrame(tick);
    }, [disabled, onEndWalk, cancelHold]);

    const handlePointerDown = (e: React.PointerEvent<HTMLButtonElement>) => {
      if (disabled) return;
      try {
        e.currentTarget.setPointerCapture(e.pointerId);
      } catch {
        // Ignore pointer capture errors
      }
      startHold();
    };

    const handlePointerUp = (e: React.PointerEvent<HTMLButtonElement>) => {
      try {
        if (e.currentTarget.hasPointerCapture(e.pointerId)) {
          e.currentTarget.releasePointerCapture(e.pointerId);
        }
      } catch {
        // Ignore
      }
      cancelHold();
    };

    const handlePointerCancel = (e: React.PointerEvent<HTMLButtonElement>) => {
      try {
        if (e.currentTarget.hasPointerCapture(e.pointerId)) {
          e.currentTarget.releasePointerCapture(e.pointerId);
        }
      } catch {
        // Ignore
      }
      cancelHold();
    };

    const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
      e.preventDefault();
      if (disabled) return;
      // If the 1s hold already finished and triggered the action, ignore subsequent click
      if (hasTriggeredRef.current) {
        hasTriggeredRef.current = false;
        return;
      }
      cancelHold();
      onEndWalk({ fromHold: false });
    };

    useEffect(() => {
      return () => {
        if (animationFrameRef.current) {
          cancelAnimationFrame(animationFrameRef.current);
        }
      };
    }, []);

    // Calculate SVG stroke offset for circular progress (circle r=26, circumference = 2 * PI * 26 ≈ 163.36)
    const radius = 26;
    const circumference = 2 * Math.PI * radius;
    const strokeDashoffset = circumference - (holdProgress / 100) * circumference;

    return (
      <div className="absolute bottom-8 inset-x-0 z-30 flex items-center justify-center gap-6 px-4 pointer-events-none select-none">
        <div className="pointer-events-auto flex items-center gap-5 p-2 rounded-full bg-background/85 backdrop-blur-md border border-border/70 shadow-xl">
          {/* Hidden Camera Input with environment capture */}
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            capture="environment"
            className="hidden"
            tabIndex={-1}
            onChange={handleFileChange}
          />

          <LiveCamera
            open={isLiveCameraOpen}
            onClose={() => setIsLiveCameraOpen(false)}
            onCapture={(file) => {
              setIsLiveCameraOpen(false);
              onPhotoSelected?.(file);
            }}
            onChooseFile={() => {
              setIsLiveCameraOpen(false);
              fileInputRef.current?.click();
            }}
          />

          {/* Camera Capture Trigger */}
          <button
            type="button"
            onClick={handleCameraClick}
            aria-label="Capture specimen"
            className="flex items-center justify-center w-14 h-14 rounded-full bg-muted/80 hover:bg-muted text-foreground border border-border/60 transition-transform active:scale-95 shadow-sm cursor-pointer"
          >
            <Camera className="w-6 h-6 text-primary" />
          </button>

          {/* Voice Note Trigger */}
          <button
            type="button"
            onClick={onMicClick}
            aria-label="Record voice note"
            className="flex items-center justify-center w-14 h-14 rounded-full bg-muted/80 hover:bg-muted text-foreground border border-border/60 transition-transform active:scale-95 shadow-sm cursor-pointer"
          >
            <Mic className="w-6 h-6 text-primary" />
          </button>

          {/* Hold or Tap "End Walk" Action (per D-13) */}
          <div className="relative flex items-center justify-center group">
            {/* Tooltip / Status hint pill */}
            {isHolding ? (
              <div className="absolute -top-10 left-1/2 -translate-x-1/2 px-2.5 py-1 rounded-full bg-background/95 backdrop-blur-md border border-destructive/40 shadow-lg text-[11px] font-semibold text-destructive whitespace-nowrap animate-in fade-in zoom-in-95 pointer-events-none">
                Ending walk...
              </div>
            ) : (
              <div className="hidden sm:group-hover:flex absolute -top-10 left-1/2 -translate-x-1/2 px-2.5 py-1 rounded-full bg-background/90 backdrop-blur-md border border-border shadow-md text-[11px] font-medium text-muted-foreground whitespace-nowrap pointer-events-none">
                Hold to finish, or click to confirm
              </div>
            )}

            {/* Circular SVG Progress Ring */}
            <svg
              className="absolute inset-0 w-16 h-16 pointer-events-none -rotate-90"
              viewBox="0 0 64 64"
            >
              {/* Background track */}
              <circle
                cx="32"
                cy="32"
                r={radius}
                className="text-border/40"
                strokeWidth="3.5"
                stroke="currentColor"
                fill="transparent"
              />
              {/* Animated progress ring */}
              <circle
                cx="32"
                cy="32"
                r={radius}
                className="text-[#DC2626] transition-all"
                strokeWidth="4"
                strokeDasharray={circumference}
                strokeDashoffset={strokeDashoffset}
                strokeLinecap="round"
                stroke="currentColor"
                fill="transparent"
              />
            </svg>

            {/* Core Button (min 48px touch target: w-14 h-14 = 56px) */}
            <button
              type="button"
              aria-label="End walk session (hold 1s or tap to confirm)"
              disabled={disabled}
              onPointerDown={handlePointerDown}
              onPointerUp={handlePointerUp}
              onPointerCancel={handlePointerCancel}
              onClick={handleClick}
              className={`relative flex items-center justify-center w-14 h-14 rounded-full transition-all duration-150 cursor-pointer shadow-md select-none touch-none active:scale-95 ${
                isHolding
                  ? 'bg-destructive text-destructive-foreground scale-95 shadow-destructive/20 ring-2 ring-destructive/40'
                  : 'bg-destructive/90 hover:bg-destructive text-white'
              }`}
            >
              <Square className="w-5 h-5 fill-current" />
            </button>
          </div>
        </div>
      </div>
    );
  }
);

