12: export function generateSyntheticLoop(
13:   centerLng: number,
14:   centerLat: number,
15:   targetMeters: number
16: ): [number, number][] {
17:   // Approximate radius for a circle with circumference = targetMeters
18:   const radiusMeters = targetMeters / (2 * Math.PI);
19: 
20:   // Degrees conversion
21:   const metersPerDegreeLat = 111320;
22:   const metersPerDegreeLng = 111320 * Math.cos((centerLat * Math.PI) / 180);
23: 
24:   const numPoints = 28;
25:   const coordinates: [number, number][] = [];
26: 
27:   // Start with exact origin point
28:   coordinates.push([centerLng, centerLat]);
29: 
30:   for (let i = 1; i < numPoints; i++) {
31:     const angle = (i / numPoints) * 2 * Math.PI;
32: 
33:     // Organic perturbation so it's not a rigid mechanical circle
34:     const perturbation = 1 + 0.08 * Math.sin(3 * angle) + 0.04 * Math.cos(5 * angle);
35:     const r = radiusMeters * perturbation;
36: 
37:     // Offset coordinates slightly so the start is tangent to the circle
38:     const dLat = (r * Math.sin(angle)) / metersPerDegreeLat;
39:     const dLng = (r * (1 - Math.cos(angle))) / metersPerDegreeLng;
40: 
41:     const lat = centerLat + dLat;
42:     const lng = centerLng + dLng;
43: 
44:     coordinates.push([lng, lat]);
45:   }
46: 
47:   // Close the loop back at the origin point
48:   coordinates.push([centerLng, centerLat]);
49: 
50:   return coordinates;
51: }
