        preference: "recommended",
        options: {
          round_trip: {
            length: targetDist,
            points: 3,
            seed: s
          }
        }
      })
    });
    if (!res.ok) continue;
    const json = await res.json();
    const feat = json.features?.[0];
    const dist = feat?.properties?.summary?.distance;
    const coords = feat?.geometry?.coordinates;
    if (!dist || !coords) continue;

    const diff = Math.abs(dist - targetDist);
    console.log(`Attempt seed ${s}: distance = ${dist.toFixed(0)}m (diff: ${diff.toFixed(0)}m)`);
    if (diff < bestDiff) {
