    const style = JSON.parse(data);

    // Transform layers for high-contrast, beautiful dark mode
    for (const layer of style.layers) {
      if (layer.type === "background") {
        layer.paint = { "background-color": "#111622" };
      }

      if (layer.type === "raster") {
        layer.paint = { "raster-opacity": 0.05 };
      }

      if (layer.type === "fill") {
        const id = layer.id;
        if (id.includes("park") || id.includes("wood") || id.includes("grass")) {
          layer.paint = { ...layer.paint, "fill-color": "#14261c", "fill-opacity": 0.85 };
        } else if (id.includes("water")) {
          layer.paint = { ...layer.paint, "fill-color": "#0d1b2a", "fill-opacity": 0.95 };
        } else if (id.includes("building")) {
          layer.paint = { ...layer.paint, "fill-color": "#1e2535", "fill-opacity": 0.9 };
        } else if (id.includes("residential")) {
          layer.paint = { ...layer.paint, "fill-color": "#151b27", "fill-opacity": 0.7 };
