          layer.paint = { ...layer.paint, "fill-color": "#1a2130", "fill-opacity": 0.8 };
        } else {
          // General fill
          if (layer.paint && layer.paint["fill-color"]) {
            layer.paint["fill-color"] = "#171e2b";
          }
        }
      }

      if (layer.type === "line") {
        const id = layer.id;
        if (id.includes("casing")) {
          layer.paint = { ...layer.paint, "line-color": "#0f141f" };
        } else if (id.includes("path") || id.includes("pedestrian")) {
          layer.paint = { ...layer.paint, "line-color": "#234e3b" };
        } else if (id.includes("motorway") || id.includes("trunk")) {
          layer.paint = { ...layer.paint, "line-color": "#475569" };
        } else if (id.includes("primary") || id.includes("secondary") || id.includes("tertiary")) {
          layer.paint = { ...layer.paint, "line-color": "#334155" };
        } else if (id.includes("park_outline")) {
          layer.paint = { ...layer.paint, "line-color": "#1e3a2b" };
        } else if (id.includes("water")) {
          layer.paint = { ...layer.paint, "line-color": "#1e3a5f" };
        } else if (id.includes("boundary")) {
          layer.paint = { ...layer.paint, "line-color": "#475569" };
        } else {
          if (layer.paint && layer.paint["line-color"]) {
            layer.paint["line-color"] = "#273244";
          }
        }
      }

      if (layer.type === "symbol") {
        const id = layer.id;
        if (!layer.paint) layer.paint = {};

        if (id.includes("water")) {
          layer.paint["text-color"] = "#7dd3fc";
          layer.paint["text-halo-color"] = "#0a1120";
