  if (l.id === "building") {
    l.paint = {
      "fill-color": "#1c2333",
      "fill-outline-color": "#273248",
      "fill-opacity": 0.85
    };
  }
  if (l.id === "building-3d") {
    l.paint = {
      "fill-extrusion-base": ["get", "render_min_height"],
      "fill-extrusion-color": "#222c3f",
      "fill-extrusion-height": ["get", "render_height"],
      "fill-extrusion-opacity": 0.85
    };
  }
}

fs.writeFileSync("public/styles/dark-liberty.json", JSON.stringify(style, null, 2));
console.log("Successfully updated building & building-3d in dark-liberty.json!");
'

